/* Onda "coming soon" nell'intro: compare come nella pagina coming soon (rivelazione da sinistra),
   resta un istante con il suo galleggiamento e poi parte in un vortice. Disegnata in WebGL,
   immagine incorporata per funzionare anche aprendo il sito da file. */
(function(){
  var WAVE_SRC='data:image/webp;base64,';
  var ROT=-9.25*Math.PI/180, ASPECT=2.3195;
  function bez(x1,y1,x2,y2){return function(t){var lo=0,hi=1,m,x;for(var i=0;i<24;i++){m=(lo+hi)/2;x=3*(1-m)*(1-m)*m*x1+3*(1-m)*m*m*x2+m*m*m;if(x<t)lo=m;else hi=m;}m=(lo+hi)/2;return 3*(1-m)*(1-m)*m*y1+3*(1-m)*m*m*y2+m*m*m;};}
  var easeReveal=bez(.65,0,.2,1);
  window.arraraWaveIntro=function(intro){
    var cv=document.createElement('canvas');
    cv.className='site-intro-wave';cv.setAttribute('aria-hidden','true');
    var gl=cv.getContext('webgl',{premultipliedAlpha:true,alpha:true});
    if(!gl) return {start:function(){},stop:function(){}};
    var vs='attribute vec2 p;void main(){gl_Position=vec4(p,0.,1.);}';
    var fs='precision highp float;uniform sampler2D tx;uniform vec2 res;uniform vec2 C;uniform vec2 S;uniform float rev,op,fly,tm,k;'
    +'const float ROT='+ROT.toFixed(6)+';'
    +'vec4 samp(vec2 p,float f){'
    +' float e=pow(f,1.2);'
    +' vec2 cm=C+vec2(-260.*e*k+60.*k*sin(f*9.)*e,1150.*e*k+40.*k*sin(f*7.+1.)*e);'
    +' float sc=1.+.25*e;vec2 d=p-cm;float r=length(d);'
    +' float a=4.*e*exp(-r/(420.*k))+.7*e;float ca=cos(a),sa=sin(a);'
    +' vec2 s=C+vec2(ca*d.x-sa*d.y,sa*d.x+ca*d.y)/sc;'
    +' vec2 q=s-C;float cr=cos(-ROT),sr=sin(-ROT);'
    +' vec2 l=vec2(cr*q.x-sr*q.y,sr*q.x+cr*q.y);'
    +' l.y+=S.y*(.012*sin(tm*.9)+.006*sin(tm*1.7));'
    +' l.y/=mix(.7,1.,rev);l.x+=.04*S.x*(1.-rev);'
    +' vec2 uv=l/S+.5;'
    +' if(uv.x<0.||uv.x>1.||uv.y<0.||uv.y>1.||uv.x>rev) return vec4(0.);'
    +' vec4 c=texture2D(tx,uv);'
    +' float fade=1.-smoothstep(.75,1.,f);'
    +' return c*op*fade;}'
    +'void main(){vec2 p=vec2(gl_FragCoord.x,res.y-gl_FragCoord.y);vec4 o=vec4(0.);'
    +' for(int i=0;i<9;i++){float f=clamp(fly+(float(i)-4.)*.0035*step(.001,fly),0.,1.);o+=samp(p,f);}'
    +' gl_FragColor=o/9.;}';
    function sh(t,s){var o=gl.createShader(t);gl.shaderSource(o,s);gl.compileShader(o);if(!gl.getShaderParameter(o,gl.COMPILE_STATUS)&&window.console)console.warn('wave shader',gl.getShaderInfoLog(o));return o;}
    var pr=gl.createProgram();gl.attachShader(pr,sh(gl.VERTEX_SHADER,vs));gl.attachShader(pr,sh(gl.FRAGMENT_SHADER,fs));gl.linkProgram(pr);
    if(!gl.getProgramParameter(pr,gl.LINK_STATUS)) return {start:function(){},stop:function(){}};
    gl.useProgram(pr);
    var buf=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,buf);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array([-1,-1,1,-1,-1,1,1,1]),gl.STATIC_DRAW);
    var loc=gl.getAttribLocation(pr,'p');gl.enableVertexAttribArray(loc);gl.vertexAttribPointer(loc,2,gl.FLOAT,false,0,0);
    var U={};['tx','res','C','S','rev','op','fly','tm','k'].forEach(function(n){U[n]=gl.getUniformLocation(pr,n);});
    var tex=gl.createTexture(),ready=false,img=new Image();
    img.onload=function(){gl.bindTexture(gl.TEXTURE_2D,tex);gl.pixelStorei(gl.UNPACK_PREMULTIPLY_ALPHA_WEBGL,true);
      gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA,gl.RGBA,gl.UNSIGNED_BYTE,img);
      gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MIN_FILTER,gl.LINEAR);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MAG_FILTER,gl.LINEAR);
      gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_S,gl.CLAMP_TO_EDGE);gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_T,gl.CLAMP_TO_EDGE);ready=true;};
    img.src=WAVE_SRC;
    intro.insertBefore(cv,intro.querySelector('.site-intro-mark'));
    var raf=0,t0=0,running=false,REV=1500,FLY0=2300,FLYD=800;
    function size(){var d=Math.min(window.devicePixelRatio||1,2);cv.width=Math.round(innerWidth*d);cv.height=Math.round(innerHeight*d);gl.viewport(0,0,cv.width,cv.height);return d;}
    function draw(el){
      var d=size();
      var W=innerWidth,H=innerHeight,Ww=W*1.0853,Wh=Ww/ASPECT;
      var rt=Math.min(el/REV,1),rev=easeReveal(rt);
      var op=.2+.8*Math.min(rt/.6,1);
      var fo=Math.min(Math.max((el-FLY0)/FLYD,0),1);fo=fo*fo*(3-2*fo);var fly=0;op=op*(1-fo);
      gl.clearColor(0,0,0,0);gl.clear(gl.COLOR_BUFFER_BIT);
      if(ready){
        gl.uniform1i(U.tx,0);gl.uniform2f(U.res,cv.width,cv.height);
        gl.uniform2f(U.C,(W/2+.00271*Ww)*d,(H*.95)*d);gl.uniform2f(U.S,Ww*d,Wh*d);
        gl.uniform1f(U.rev,rev);gl.uniform1f(U.op,op);gl.uniform1f(U.fly,fly);gl.uniform1f(U.tm,Math.min(el,FLY0)/1000*2.2);gl.uniform1f(U.k,H/1080*d);
        gl.drawArrays(gl.TRIANGLE_STRIP,0,4);
      }
    }
    function frame(now){
      if(!running) return;
      var el=now-t0;draw(el);
      if(el<FLY0+FLYD+50) raf=requestAnimationFrame(frame); else {running=false;cv.style.display='none';}
    }
    return {
      onstart:null,
      start:function(){if(running)return;running=true;t0=performance.now();raf=requestAnimationFrame(frame);},
      seek:function(ms){draw(ms);},
      stop:function(){running=false;cancelAnimationFrame(raf);cv.style.display='none';}
    };
  };
})();
